SELECT 
FROM soo_breakeven_analysis
WHERE tenant_id = #{tenantId}
  AND status = 'active'
ORDER BY created_at DESC

    LIMIT #{limit}

SELECT analysis_type, COUNT(*) as count, AVG(breakeven_point) as avg_breakeven_point, AVG(margin_safety_ratio) as avg_margin_safety_ratio, AVG(reasonability_score) as avg_reasonability_score, MAX(created_at) as latest_created FROM soo_breakeven_analysis WHERE tenant_id = #{tenantId} AND status = 'active'
AND analysis_period = #{analysisPeriod}
GROUP BY analysis_type ORDER BY count DESC
